"""Generator of baseline-readings.json.

Run ONCE at 032957c, before any production change of the CP-1 instruction PR. Do NOT re-run it to
"fix" a failing comparison: the file is a regression snapshot of what production code read then.

    uv run python tests/fixtures/cp1-instruction-pr/make_baseline.py
"""

import json
from pathlib import Path

from credit_os import store

from deploy_workflow.owners.cpos_cp1_check import cp1_issues

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).parent


def readings(path: Path) -> dict:
    text = path.read_text(encoding="utf-8")
    fields = store.reader_fields(store.sections_of(text))
    fields.update(store.report_fields(store.sections_of(text), fields["summary"]))
    return {"library": fields, "cp1_check_issues": list(cp1_issues(text))}


def main() -> None:
    key = json.loads((HERE / "answer-key.json").read_text(encoding="utf-8"))
    out = {
        "_scope": (
            "Regression snapshot generated by production code at 032957c; "
            "not an independent expected value."
        ),
        "files": {name: readings(ROOT / name) for name in key["unchanged"]["files"]},
    }
    text = json.dumps(out, sort_keys=True, indent=1, ensure_ascii=False) + "\n"
    (HERE / "baseline-readings.json").write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
